class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def f(x):
            # number of operations to reduce x to 0
            cnt = 0
            while x > 0:
                x //= 4
                cnt += 1
            return cnt

        total = 0
        for l, r in queries:
            # max operations needed for any element in [l, r]
            max_ops = max(f(l), f(r))
            # binary search for smallest x such that f(x) >= max_ops
            lo, hi = l, r
            while lo < hi:
                mid = (lo + hi) // 2
                if f(mid) >= max_ops:
                    hi = mid
                else:
                    lo = mid + 1
            # operations needed = max_ops + ceil((r - x + 1) / 2)
            ops = max_ops + (r - lo + 2) // 2
            total += ops
        return total

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_upto(n):
            if n < 1:
                return 0
            s = str(n)
            digits = [int(c) for c in s]
            length = len(digits)

            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(pos, tight, started, sum_digits, prod_digits):
                if pos == length:
                    if not started:
                        return 0
                    if sum_digits == 0:
                        return 0
                    if prod_digits % sum_digits == 0:
                        return 1
                    return 0

                limit = digits[pos] if tight else 9
                total = 0
                for d in range(0, limit + 1):
                    new_tight = tight and (d == limit)
                    new_started = started or (d != 0)
                    if not new_started:
                        total += dp(pos + 1, new_tight, new_started, 0, 1)
                    else:
                        new_sum = sum_digits + d
                        if d == 0:
                            new_prod = 0
                        else:
                            new_prod = prod_digits * d
                        total += dp(pos + 1, new_tight, new_started, new_sum, new_prod)
                return total

            return dp(0, True, False, 0, 1)

        return count_upto(r) - count_upto(l - 1)

