class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        n = len(points)

        # Binary search for the maximum minimum Manhattan distance
        def can_select(min_dist: int) -> bool:
            # Try to select k points with minimum distance >= min_dist
            # Use backtracking
            def backtrack(start: int, selected: List[int]) -> bool:
                if len(selected) == k:
                    return True
                # Need to select k - len(selected) more points
                remaining_needed = k - len(selected)
                # Pruning: not enough points left
                if start + remaining_needed > n:
                    return False

                for i in range(start, n):
                    # Check if this point is far enough from all selected points
                    valid = True
                    for s in selected:
                        dist = abs(points[i][0] - points[s][0]) + abs(points[i][1] - points[s][1])
                        if dist < min_dist:
                            valid = False
                            break
                    if valid:
                        selected.append(i)
                        if backtrack(i + 1, selected):
                            return True
                        selected.pop()

                return False

            return backtrack(0, [])

        # Maximum possible Manhattan distance is 2*side (opposite corners)
        lo, hi = 0, 2 * side
        ans = 0

        while lo <= hi:
            mid = (lo + hi) // 2
            if can_select(mid):
                ans = mid
                lo = mid + 1
            else:
                hi = mid - 1

        return ans

