    if not data:
        return
    it = iter(data)
    N = int(next(it))
    K = int(next(it))
    A = [int(next(it)) for _ in range(N)]
    maxA = max(A)
    # frequency of each value
    freq = [0] * (maxA + 1)
    for v in A:
        freq[v] += 1

    # For each g, count how many elements are multiples of g
    mult = [0] * (maxA + 1)
    for g in range(1, maxA + 1):
        s = 0
        for m in range(g, maxA + 1, g):
            s += freq[m]
        mult[g] = s

    # For each g, check if we can pick K elements all divisible by g
    good = [False] * (maxA + 1)
    for g in range(1, maxA + 1):
        if mult[g] >= K:
            good[g] = True

    # Build best[g] = largest divisor d of g such that good[d] is True, or 1 if none
    best = [1] * (maxA + 1)
    for d in range(1, maxA + 1):
        if not good[d]:
            continue
        for m in range(d, maxA + 1, d):
            # d divides m, and d is a candidate answer for elements equal to m
            if best[m] < d:
                best[m] = d

    out_lines = [str(best[v]) for v in A]
    sys.stdout.write("\n".join(out_lines))

