class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def canAchieve(L):
            # Check if we can partition s into substrings of length at most L
            # with at most numOps flips total
            # We use DP: dp[i] = minimum flips to make s[0..i-1] valid
            INF = float('inf')
            dp = [INF] * (n + 1)
            dp[0] = 0
            for i in range(n):
                if dp[i] == INF:
                    continue
                # Try to end a block at position j-1 (inclusive), starting at i
                for j in range(i + 1, min(n + 1, i + L + 1)):
                    # Count flips needed to make s[i..j-1] all same char
                    length = j - i
                    ones = s[i:j].count('1')
                    zeros = length - ones
                    flips = min(ones, zeros)
                    if dp[i] + flips <= numOps:
                        dp[j] = min(dp[j], dp[i] + flips)
            return dp[n] <= numOps

        # Binary search on L
        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi) // 2
            if canAchieve(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

