    for _ in range(M):
        d, c = input().split()
        c = int(c)
        ops.append((d, c))

    # Process operations
    x, y = Sx, Sy
    count = 0
    visited = set()

    # For fast lookup of houses by x or y
    # Use dictionary mapping x -> set of y, and y -> set of x
    house_by_x = {}
    house_by_y = {}
    for (hx, hy), idx in houses.items():
        if hx not in house_by_x:
            house_by_x[hx] = {}
        house_by_x[hx][hy] = idx
        if hy not in house_by_y:
            house_by_y[hy] = {}
        house_by_y[hy][hx] = idx

    for d, c in ops:
        if d == 'U':
            # Moving up: y increases
            target_y = y + c
            if x in house_by_x:
                # Find all houses with this x and y in (y, target_y]
                hdict = house_by_x[x]
                # Get keys in range (y, target_y]
                keys = [ky for ky in hdict if y < ky <= target_y]
                for ky in keys:
                    idx = hdict[ky]
                    if idx not in visited:
                        visited.add(idx)
                        count += 1
            y = target_y
        elif d == 'D':
            # Moving down: y decreases
            target_y = y - c
            if x in house_by_x:
                hdict = house_by_x[x]
                keys = [ky for ky in hdict if target_y <= ky < y]
                for ky in keys:
                    idx = hdict[ky]
                    if idx not in visited:
                        visited.add(idx)
                        count += 1
            y = target_y
        elif d == 'R':
            # Moving right: x increases
            target_x = x + c
            if y in house_by_y:
                hdict = house_by_y[y]
                keys = [kx for kx in hdict if x < kx <= target_x]
                for kx in keys:
                    idx = hdict[kx]
                    if idx not in visited:
                        visited.add(idx)
                        count += 1
            x = target_x
        elif d == 'L':
            # Moving left: x decreases
            target_x = x - c
            if y in house_by_y:
                hdict = house_by_y[y]
                keys = [kx for kx in hdict if target_x <= kx < x]
                for kx in keys:
                    idx = hdict[kx]
                    if idx not in visited:
                        visited.add(idx)
                        count += 1
            x = target_x

