class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter

        n = len(s)
        freq = [0] * 26
        for ch in s:
            freq[ord(ch) - ord('a')] += 1

        # Try all possible target frequencies k from 1 to n
        best = n  # worst case: delete all characters

        for k in range(1, n + 1):
            operations = 0
            for f in freq:
                if f == 0:
                    # Need to insert k characters
                    operations += k
                else:
                    # Choose to either delete (f-k), or insert (k-f), 
                    # or change some characters to other letters
                    diff = abs(f - k)
                    if f > k:
                        # Delete (f - k) characters
                        operations += diff
                    else:
                        # Insert (k - f) characters
                        operations += diff
            best = min(best, operations)

        return best

import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    A = [0] * (N + 1)          # 1‑based
    for i in range(1, N + 1):
        A[i] = int(next(it))

    # prefix sums
    pref = [0] * (N + 1)
    for i in range(1, N + 1):
        pref[i] = pref[i - 1] + A[i]

    # right intervals: left‑to‑right stack
    R = [N + 1] * (N + 2)      # R[i] = nearest stack index to the right, N+1 if none
    stack = []
    for i in range(1, N + 1):
        while stack and A[stack[-1]] >= A[i]:
            stack.pop()
        if stack:
            R[i] = stack[-1]   # the next stack element to the right
        else:
            R[i] = N + 1
        stack.append(i)

    # left intervals: right‑to‑left stack
    L = [0] * (N + 2)          # L[i] = nearest stack index to the left, 0 if none
    stack = []
    for i in range(N, 0, -1):
        while stack and A[stack[-1]] >= A[i]:
            stack.pop()
        if stack:
            L[i] = stack[-1]   # the next stack element to the left
        else:
            L[i] = 0
        stack.append(i)

    # compute answers
    ans = [0] * (N + 1)
    for k in range(1, N + 1):
        # sum of interval [L[k]+1 , R[k]-1]
        ans[k] = pref[R[k] - 1] - pref[L[k]]

    # output
    out = ' '.join(str(ans[i]) for i in range(1, N + 1))
    sys.stdout.write(out)

