    solve()

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        parent = list(range(n))
        size = [1] * n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            rx, ry = find(x), find(y)
            if rx == ry:
                return False
            if size[rx] < size[ry]:
                rx, ry = ry, rx
            parent[ry] = rx
            size[rx] += size[ry]
            return True

        # Bucket nodes by their value
        max_val = max(max(nums), threshold)
        buckets = [[] for _ in range(max_val + 1)]
        for i, v in enumerate(nums):
            if v <= threshold:
                buckets[v].append(i)

        # Sieve-like union: for each value d, union all nodes whose values are multiples of d
        # where d <= threshold. If two nodes share a common divisor d <= threshold, they
        # are connected (lcm(a,b) <= threshold iff gcd(a,b) * lcm_div >= ..., actually
        # a simpler sufficient condition: if gcd(a,b) * 1 <= threshold when we check
        # via common multiples).
        # 
        # Key insight: lcm(a,b) <= threshold implies there exists some d = gcd(a,b) such
        # that a and b are both multiples of d, and a*b/gcd(a,b) <= threshold.
        # 
        # For small values, union via sieve approach.

        for d in range(1, threshold + 1):
            nodes_in_bucket = []
            for multiple in range(d, max_val + 1, d):
                nodes_in_bucket.extend(buckets[multiple])

            if len(nodes_in_bucket) > 1:
                for i in range(1, len(nodes_in_bucket)):
                    union(nodes_in_bucket[0], nodes_in_bucket[i])

        # Count distinct components
        roots = set()
        for i in range(n):
            roots.add(find(i))

        return len(roots)
